import{_ as o,h as l,i as t,c as r,v as e,p as n,x as s,m as d,e as m,S as _}from"./chunks/framework.Dvtg8yj2.js";const k=JSON.parse('{"title":"Attention 中的缩放、温度与数值稳定","description":"","frontmatter":{"title":"Attention 中的缩放、温度与数值稳定","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-scale-stability.md","filePath":"llm/attention-scale-stability.md","lastUpdated":1788454257000}'),p={name:"llm/attention-scale-stability.md"};function h(c,a,u,f,A,x){const i=l("Mermaid");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="attention-中的缩放、温度与数值稳定" tabindex="-1">Attention 中的缩放、温度与数值稳定 <a class="header-anchor" href="#attention-中的缩放、温度与数值稳定" aria-label="Permalink to &quot;Attention 中的缩放、温度与数值稳定&quot;">​</a></h1><div class="epigraph"><p>当键的维度较大时，点积的量级会膨胀，把 softmax 推入梯度极小的区域；除以维度的平方根，是为了把打分拉回可训练的尺度。</p><footer>—— Vaswani et al., Attention Is All You Need, NeurIPS 2017</footer></div><p>缩放点积注意力的公式看起来只多了一个 \\(\\sqrt{d_k}\\)，工程上却要同时对付三件常被混为一谈的事：训练时如何避免 softmax 饱和，推理时如何用温度改变分布锋利程度，以及半精度下指数与累加如何不溢出、不变成 NaN。Vaswani 等人只明确写了第一件。温度是同一数学对象上的自由参数，数值稳定则是 softmax 实现必须具备的平移不变处理。本篇把尺度问题从 SDPA 的「是什么」里抽出来，专讲「分数送到 softmax 之前发生了什么」。二次复杂度、多头结构在此只作为尺度问题的背景，不展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>softmax 把实数向量变成概率，对输入的仿射尺度极敏感。令 \\(z\\) 为 logits，若把 \\(z\\) 乘以常数 \\(c&gt;1\\)，分布更接近 one-hot；乘以 \\(c&lt;1\\)，更接近均匀。点积 \\(q^\\top k\\) 在分量方差约为 1 时，自身方差约为 \\(d_k\\)，等效于把 \\(c\\) 设成 \\(\\sqrt{d_k}\\)。宽度一加，未缩放的注意力会在训练早期就变成几乎硬选择，梯度 \\(p_i(1-p_i)\\) 接近 0，深层更难把路由学开。</p><p>半精度把问题从「梯度太小」变成「中间值太大」。<code>exp</code> 在 FP16 大约在输入大于 11 附近溢出到无穷，softmax 的分母变成 NaN。即便有 \\(\\sqrt{d_k}\\)，长序列上仍可能出现个别极大 logits。稳定实现依赖的不是再除一个常数，而是 softmax 的平移不变性：减去行最大值后再指数。三件事纠缠在同一条数据路径上，调试时必须分开看是饱和、是温度策略，还是浮点溢出。</p><h3 id="方差计算给出的尺度" tabindex="-1">方差计算给出的尺度 <a class="header-anchor" href="#方差计算给出的尺度" aria-label="Permalink to &quot;方差计算给出的尺度&quot;">​</a></h3><p>设 \\(q,k\\) 分量 i.i.d.、零均值、单位方差，则 \\(\\mathrm{Var}(q^\\top k)=d_k\\)。除以 \\(\\sqrt{d_k}\\) 后方差回到 1，典型 logits 落在 softmax 曲线的中段。若投影矩阵的初始化方差不是 \\(1/d\\)，上述假设立刻失效：He/Xavier 的具体系数、是否对 \\(Q,K\\) 做归一化，都会平移这个「1」。因此 \\(\\sqrt{d_k}\\) 是在一组初始化惯例下的校准，不是与参数无关的定理。</p><p><span class="marginnote">QK-Norm 在部分当代模型里出现，是对同一尺度问题的第二道保险：在点积前把 \\(q,k\\) 拉到固定范数，再点积、再缩放。它不取代 \\(\\sqrt{d_k}\\)，而是削弱「投影把向量放飞」这条路径。本篇不把它当成主题，只指出：范数控制与除常数是两类杠杆，可以叠用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准训练前向为</p> \\[s_{ij}=\\frac{q_i^\\top k_j}{\\sqrt{d_k}},\\qquad \\alpha_{ij}=\\frac{e^{s_{ij}}}{\\sum_{\\ell}e^{s_{i\\ell}}}. \\]<p>温度 \\(\\tau&gt;0\\) 写在分母上：</p> \\[\\alpha_{ij}=\\frac{e^{s_{ij}/\\tau}}{\\sum_{\\ell}e^{s_{i\\ell}/\\tau}}. \\]<p>\\(\\tau=1\\) 时回到 SDPA 已缩放的分数；\\(\\tau&lt;1\\) 更锋利，\\(\\tau&gt;1\\) 更平。训练期 \\(\\tau\\) 几乎总是 1，缩放已经由 \\(\\sqrt{d_k}\\) 承担。推理期语言模型有时对最终词表 softmax 设温度，那是输出层的 \\(\\tau\\)，与注意力内部的 \\(\\tau\\) 不是同一处旋钮。若有人在注意力分数上再除温度，等于把有效缩放改成 \\(\\sqrt{d_k}\\,\\tau\\)，需要与检查点训练时的设定一致，否则路由分布整体偏移。</p><h3 id="稳定-softmax-减最大值" tabindex="-1">稳定 softmax：减最大值 <a class="header-anchor" href="#稳定-softmax-减最大值" aria-label="Permalink to &quot;稳定 softmax：减最大值&quot;">​</a></h3><p>对每一行令 \\(m_i=\\max_j s_{ij}\\)，计算</p> \\[\\alpha_{ij}=\\frac{e^{s_{ij}-m_i}}{\\sum_{\\ell}e^{s_{i\\ell}-m_i}}. \\]<p>这不改变数学结果，但使指数的最大输入为 0，消除溢出。分母是 log-sum-exp 的指数形式。FlashAttention 在分块时维护各块的行最大值与归一化因子，按块更新，本质是在线算法版的同一恒等式。混合精度里常见做法是：矩阵乘用 FP16/BF16，softmax 提到 FP32 再写回。BF16 的指数范围更宽，溢出少，但精度粗，减最大值仍然值得做。</p>',19)),(t(),n(_,null,{default:s(()=>[m(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%82%B9%E7%A7%AF%20QK%22%5D%20--%3E%20SC%5B%22%E9%99%A4%E4%BB%A5%20sqrt%20dk%22%5D%0A%20%20SC%20--%3E%20T%5B%22%E5%8F%AF%E9%80%89%E9%99%A4%E4%BB%A5%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20T%20--%3E%20MX%5B%22%E6%AF%8F%E8%A1%8C%E5%87%8F%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%0A%20%20MX%20--%3E%20EX%5B%22%E6%8C%87%E6%95%B0%22%5D%0A%20%20EX%20--%3E%20Z%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E6%88%90%E6%9D%83%E9%87%8D%22%5D%0A%20%20Z%20--%3E%20V%5B%22%E4%B9%98%20Value%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缩放改变的是训练动态。梯度经过 softmax 的雅可比，饱和区几乎切断对 \\(W^Q,W^K\\) 的更新，值侧 \\(W^V\\) 仍可能通过「已经几乎 one-hot 的权重」学习被选中的内容。于是模型会先学会硬选择再难以改路由，表现为注意力图很「自信」但不会随数据调整。合适的尺度让早期权重偏软，路由与内容可以一起动。</p><p>温度在推理时移动的是同一雅可比的工作点。低温度放大已有的分数差距，错误的高分会被进一步锁死；高温度把质量分给更多键，生成更散，也更可能读到不相关上下文。注意力温度与词表温度叠加时，前者改内部读取，后者改外部采样，效果不可互换：把词表温度调低无法修复内部已经读错的记忆。</p><p><span class="marginnote">因果掩码使用的大负数必须落在当前精度的安全区。FP16 下若写成 \\(-1\\times 10^{30}\\)，减最大值之前就可能已经是负无穷，某些核会把整行变成 NaN。实践中用大约 \\(-10^4\\) 到 \\(-10^5\\) 的有限值，再依赖减最大值。稳定性和掩码常数是一套问题。</span></p><h3 id="长度增长如何再次破坏尺度" tabindex="-1">长度增长如何再次破坏尺度 <a class="header-anchor" href="#长度增长如何再次破坏尺度" aria-label="Permalink to &quot;长度增长如何再次破坏尺度&quot;">​</a></h3><p>即使 \\(d_k\\) 固定，softmax 分母是 \\(m\\) 项之和。序列变长时，若分数的均值不随 \\(m\\) 下降，平均权重按 \\(1/m\\) 变稀，真正的高峰需要更大的 logit 间隙才能冒出来。这不是 \\(\\sqrt{d_k}\\) 设计时针对的效应，却会在长上下文里表现为「注意力被稀释」。ALiBi、注意力汇点、窗口注意力，都是在结构上限制有效 \\(m\\) 或改写分数，从而间接管理尺度。把长上下文失败全部归咎于「没除平方根」是误诊。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(\\sqrt{d_k}\\) 与学习率、初始化、残差缩放耦合。Pre-LN 使深层输入尺度更稳，间接减轻 logits 爆炸；把学习率开得过大，仍会在几步内把 \\(Q,K\\) 打飞。工程上应监控注意力 logits 的均方或最大值，而不是只看损失。溢出表现为 NaN，饱和表现为 logits 极大但损失还在缓慢下降——后者更隐蔽。</p><p>不要把输出层温度、分类蒸馏温度、注意力温度用同一个配置项控制。三处 softmax 各有语义。训练中途改 \\(d_k\\)（例如改头宽）必须同步改缩放常数，否则等于给旧检查点换了一套温度。从 MHA 改到 GQA 时头宽通常不变，缩放不必动；若同时改 \\(d_k\\)，缩放要一起改。</p><p><span class="marginnote">「数值稳定」有时被拿来解释任何注意力改动。线性注意力换核函数、余弦注意力限制范数，确实也在管尺度，但它们改的是相容性定义，不再是 softmax 注意力。本篇的边界停在：仍用 softmax，只调节送进去的仿射尺度与实现精度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(1/\\sqrt{d_k}\\) 用来对消点积方差随头宽增长，使训练期 softmax 不至于过早饱和。</li><li>温度 \\(\\tau\\) 与缩放在数学上同类，但习惯上训练靠 \\(\\sqrt{d_k}\\)、推理才另调 \\(\\tau\\)；词表温度不是注意力温度。</li><li>减行最大值是 softmax 的平移不变实现，负责防溢出；它不替代缩放，也不改变理论分布。</li><li>混合精度下矩阵乘与 softmax 常拆开精度，掩码常数必须是当前格式下的有限大负数。</li><li>序列变长会通过分母项数再次稀释权重，这超出了 \\(\\sqrt{d_k}\\) 的设计目标。</li><li>初始化、QK-Norm、学习率与缩放是不同杠杆，出问题时应分开做消融而不是只改一个常数。</li><li>出处：Vaswani et al., <em>Attention Is All You Need</em>, NeurIPS 2017；实现层面的分块稳定 softmax 见 Dao, <em>FlashAttention</em>, 2022/2023。</li></ul>',12))])}const E=o(p,[["render",h]]);export{k as __pageData,E as default};
